import{_ as t,a as o,b as i,c as a,d as n,e as s,f as r}from"./chunks/hromadne_operace.0A3C54YA.js";import{_ as l}from"./chunks/spp_polozky3.BRDJgjmN.js";import{_ as p}from"./chunks/filtrace.B2Bh4beK.js";import{_ as d,o as c,c as h,aa as u}from"./chunks/framework.BAs_AphD.js";const m="/buildary-help-preview/media/cs/performedworks/spp_okno.png",g="/buildary-help-preview/media/cs/performedworks/spp_zahlavi2.png",f="/buildary-help-preview/media/cs/performedworks/stavy-zp.png",S=JSON.parse('{"title":"Contractor SPP Window","description":"","frontmatter":{"title":"Contractor SPP Window","wiki":"en:performedworks:application_window"},"headers":[],"relativePath":"en/performedworks/application_window.md","filePath":"en/performedworks/application_window.md","lastUpdated":1794388980000}'),b={name:"en/performedworks/application_window.md"};function y(w,e,v,P,_,k){return c(),h("div",null,[...e[0]||(e[0]=[u('<h1 id="contractor-spp-window" tabindex="-1">Contractor SPP Window <a class="header-anchor" href="#contractor-spp-window" aria-label="Permalink to &quot;Contractor SPP Window&quot;">​</a></h1><p>Performed Works between representatives of the (main) contractor and the client (investor) are carried out in the Contractor SPP process.</p><p>To work in this window, the user must have the appropriate permissions configured, i.e. the company and role assigned under Project Team Members, as described in the &quot;Setting Permissions&quot; section of the Help.</p><p>The window is divided into several separate sections, as shown in the following image:</p><img src="'+m+'" alt="" width="600" loading="lazy"><h2 id="window-header" tabindex="-1">Window Header <a class="header-anchor" href="#window-header" aria-label="Permalink to &quot;Window Header&quot;">​</a></h2><img src="'+g+'" alt="" loading="lazy"><p>The window header is used to set and display information that is essential for working in the window. The information about the period, client, and contractor determines which set of budget items and work statements is displayed and processed in the window.</p><p><strong>Period</strong> – Select a period from the available options. Creating a new period is described in a separate section of the Help.</p><p><strong>Client</strong> – If you represent the client, only the organization to which you are assigned is available. If you represent the contractor, all clients appearing in the project budget are available.</p><p><strong>Contractor</strong> – If you represent the contractor, only the organization to which you are assigned is available. If you represent the client, all contractors appearing in the project budget are available.</p><p><strong>Reports</strong> – Opens a window containing a list of Measurement Reports for the Client/Contractor pair selected in the header. A Measurement Report (ZP) is a report documenting Performed Works between a Client/Contractor pair or, where applicable, a Contractor/Subcontractor pair for a specific period.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Each ZP can have one of the following statuses:</strong></p><ul><li>Draft</li><li>Approval</li><li>Proposal Change</li><li>Closed</li></ul></div><figure class="shot" style="--w:650px;"><img src="'+f+'" alt="" loading="lazy"></figure><p><strong>Change Measurement Report Status</strong> – This section displays buttons for changing the ZP status. The available buttons depend on the current status of the Measurement Report. Changes to the ZP status are protected by permission groups, as described in the &quot;Setting Permissions&quot; section of the Help.</p><h2 id="summary-panel" tabindex="-1">Summary Panel <a class="header-anchor" href="#summary-panel" aria-label="Permalink to &quot;Summary Panel&quot;">​</a></h2><p>The Summary Panel provides an overview of information for the entire project from the perspective of the selected Client/Contractor pair.</p><img src="'+t+'" alt="" width="1200" loading="lazy"><p><strong>White section of the panel</strong> – Displays total amounts for all periods.</p><p><strong>Colored section of the panel</strong> – Displays amounts related to the period currently selected in the window header.</p><img src="'+o+'" alt="" width="100" loading="lazy"><ul><li>the home icon indicates that data for all project items is displayed</li><li>the filter icon indicates that the displayed data is aggregated only from items matching the currently selected filter.</li></ul><h2 id="items-and-consumption-in-the-current-period" tabindex="-1">Items and Consumption in the Current Period <a class="header-anchor" href="#items-and-consumption-in-the-current-period" aria-label="Permalink to &quot;Items and Consumption in the Current Period&quot;">​</a></h2><p>If no filter is active, the window always displays the items contained in the project parts selected in the Project Structure panel, for example, the items belonging to the first project object.</p><img src="'+l+'" alt="" width="1200" loading="lazy"><p><strong>The item window contains several groups of columns:</strong></p><p><strong>Item</strong> – columns containing item codes and descriptions. The Type distinguishes between a building object, project part, section, and individual items. The checkbox column is used to select items for Bulk Operations. The item name column contains an &quot;i&quot; icon that allows you to display detailed information about the item in a separate window.</p><p><strong>Remaining</strong> – this group of columns contains information about the remaining quantity and price of the item. The remaining value is also represented by an icon showing the percentage.</p><p><strong>Selected Period</strong> – this group of columns is used to enter and approve item consumption for the selected period. The columns in this group are displayed dynamically based on the status of the Measurement Report and the user&#39;s permissions. Editable cells are highlighted in yellow. The speech bubble icon allows you to add a note to the item&#39;s consumption. An orange icon indicates that a note exists. Work in this group is described in detail below.</p><p><strong>Completed</strong> – this group of columns contains information about the completed quantity and price of the item. The figures also include consumption for the Selected Period.</p><p><strong>Budget</strong> – displays information about the total quantity and price of the items. The unit price of each item is also displayed.</p><p><strong>Item Details</strong> – the window displays descriptive information about the item. It also provides summary information about its consumption status and a detailed breakdown of consumption by individual periods. The consumption details also show who approved the consumption and when. Notes related to the consumption are also available, if entered.</p><img src="'+i+'" alt="" loading="lazy"><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><figure class="shot" style="--w:300px;"><img src="'+a+'" alt="" width="300" loading="lazy"></figure><p>The Project Structure panel makes it easier to navigate the budget. The panel displays building objects, project parts, or budget sections. The structure can contain multiple levels with practically no limit.</p><p>Each level can be expanded to display the next level.</p><p>The grid then displays only the items belonging to the group selected in the Project Structure panel.</p><p>If you need to display a larger range of items, you can select multiple records in the tree using multiselect (Ctrl+click or Shift+click). Ctrl+click can also be replaced by pressing and holding the mouse button.</p><p>The panel displays a symbol and the number of unresolved and resolved items for the selected period next to each record. This is a very useful navigation aid for large projects when entering, approving, and modifying items.</p><figure class="shot" style="--w:300px;"><img src="'+n+'" alt="" width="300" loading="lazy"></figure><figure class="shot" style="--w:300px;"><img src="'+s+'" alt="" width="300" loading="lazy"></figure><p>The project structure tree can be expanded and collapsed in bulk using the control buttons above the panel.</p><p>The project structure can also be filtered based on the occurrence of a specified string.</p><p>The &quot;Hide Panel&quot; button can be used to create more space for displaying the grid contents.</p><h2 id="special-functions-panel" tabindex="-1">Special Functions Panel <a class="header-anchor" href="#special-functions-panel" aria-label="Permalink to &quot;Special Functions Panel&quot;">​</a></h2><h3 id="bulk-operations" tabindex="-1">Bulk Operations <a class="header-anchor" href="#bulk-operations" aria-label="Permalink to &quot;Bulk Operations&quot;">​</a></h3><p>– opens a list of functions that can be used to modify data for multiple items at once. Bulk Operations are always applied to the items selected (checked) in the grid. If you need to select multiple items, you can use the checkbox at a higher level.</p><figure class="shot" style="--w:300px;"><img src="'+r+'" alt="" width="200" loading="lazy"></figure><p><strong>Consumption by Amount</strong> – distributes the entered amount among the selected items. The maximum amount that can be consumed is the sum of the remaining prices of the selected items. If both positive and negative items are selected, there is no unambiguous algorithm for reaching the requested resulting price. In this situation, a positive amount is distributed only among positive items, while a negative amount is distributed only among negative items. The user is informed about this procedure by a message displayed directly in the application.</p><p><strong>Consumption by Percentage</strong> – consumes the specified percentage of the item&#39;s total quantity for each selected item. Enter only the value, without the % symbol.</p><p>If the quantity calculated from the specified percentage exceeds the item&#39;s remaining quantity, the item is consumed only up to its total quantity. This operation therefore cannot result in overconsumption. <strong>Change Item Status</strong> – changes the status of the selected items to the selected status value. This option is available only when the Measurement Report is in the &quot;Approval&quot; status.</p><p><strong>Delete Consumption</strong> – deletes all entered data for the selected items and resets them to their default status. This option is available only when the Measurement Report is in the &quot;Approval&quot; status.</p><p>Before performing a Bulk Operation, you can choose whether the item selection should remain active after the operation is completed. This can be useful if you want to perform another Bulk Operation on the same set of items.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can easily clear the item selection by double-clicking the header of the checkbox column. The first click selects all displayed items, while the second click clears the selection for all items.</p></div><h3 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h3><p>The filtering menu offers predefined filters divided into three groups, depending on which information is used for filtering. The filter is always applied to all project items, so it also affects which records are displayed in the Project Structure panel. If a particular level of the structure contains no items matching the filter, that level will not be displayed in the tree.</p><figure class="shot" style="--w:300px;"><img src="'+p+'" alt="" width="200" loading="lazy"></figure><p><strong>Item Status</strong> – allows you to filter items according to their current status. In addition to individual statuses, summary statuses can also be selected.</p><ul><li><p><strong>Open</strong> – items with the status Draft or In Negotiation, i.e. items that have not yet been resolved.</p></li><li><p><strong>Closed</strong> – items with the status Approved, Change, or Rejected, i.e. items that are considered resolved.</p></li></ul><p><strong>Consumption in the Selected Period</strong> – allows you to filter items based on whether consumption has been entered for the selected period.</p><ul><li><p><strong>Consumed</strong> – have a non-zero value in the Invoiced Quantity column.</p></li><li><p><strong>Not Consumed</strong> – have no value or a zero value in the Invoiced Quantity column.</p></li></ul><p><strong>Consumption in All Periods</strong> – allows you to filter items based on whether consumption has been entered in at least one period.</p><ul><li><p><strong>Consumed</strong> – have a non-zero value in the Invoiced Quantity column in at least one period.</p></li><li><p><strong>Not Consumed</strong> – have no value or a zero value in the Invoiced Quantity column in all periods.</p></li><li><p><strong>Fully Consumed</strong> – have zero remaining quantity.</p></li><li><p><strong>Remaining Consumption Above</strong> – items for which more than the specified percentage of the quantity remains to be consumed.</p></li><li><p><strong>Remaining Consumption Below</strong> – items for which less than the specified percentage of the quantity remains to be consumed.</p></li></ul><h3 id="search-by-name-or-code" tabindex="-1">Search by Name or Code <a class="header-anchor" href="#search-by-name-or-code" aria-label="Permalink to &quot;Search by Name or Code&quot;">​</a></h3><p>This function filters the displayed items to those containing the specified string. The Code and Description fields are searched.</p><h3 id="printing-and-exports" tabindex="-1">Printing and Exports <a class="header-anchor" href="#printing-and-exports" aria-label="Permalink to &quot;Printing and Exports&quot;">​</a></h3><p>Options for exporting to Excel and PDF are described in a separate section, SPP Outputs.</p>',68)])])}const I=d(b,[["render",y]]);export{S as __pageData,I as default};
